namespace IntentSystem.Cli.Commands;

/// <summary>
/// G842: refuses reads of the operator's Copilot and OpenCode homes and
/// planned-path overlap with those homes during cross-runtime review request
/// rendering.
/// </summary>
internal static class CrossRuntimeReviewHomeAccessGuard
{
    public static Func<string, bool>? ShouldRefusePath { get; set; }

    public static bool IsProtectedOperatorPath(string path)
    {
        if (ShouldRefusePath?.Invoke(path) == true)
        {
            return true;
        }

        var normalized = ResolvePath(path);
        foreach (var root in EnumerateProtectedHomes())
        {
            if (PathsOverlap(normalized, root))
            {
                return true;
            }
        }

        return false;
    }

    public static void GuardPath(string path)
    {
        if (IsProtectedOperatorPath(path))
        {
            throw new InvalidOperationException($"cross-runtime review must not read operator path '{path}'.");
        }
    }

    public static bool TryRefuseProtectedPath(string path, out string detail)
    {
        if (!IsProtectedOperatorPath(path))
        {
            detail = string.Empty;
            return false;
        }

        detail = $"cross-runtime review must not read operator path '{path}'.";
        return true;
    }

    public static bool TryRefusePlannedPaths(string outDir, string runtime, out string detail)
    {
        detail = string.Empty;
        var plannedPaths = EnumeratePlannedPaths(outDir, runtime)
            .Select(ResolvePath)
            .OrderByDescending(static path => path.Length)
            .ToArray();
        foreach (var home in EnumerateProtectedHomes())
        {
            foreach (var planned in plannedPaths)
            {
                if (PathsOverlap(planned, home))
                {
                    detail = $"planned path '{planned}' overlaps protected home '{home}'.";
                    return true;
                }
            }
        }

        var resolvedOutDir = ResolvePath(outDir);
        foreach (var planned in EnumeratePlannedPaths(outDir, runtime))
        {
            if (!TryValidateExistingPlannedPath(planned, resolvedOutDir, out detail))
            {
                return true;
            }
        }

        return false;
    }

    internal static IEnumerable<string> EnumerateProtectedHomes()
    {
        var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        yield return ResolvePath(Path.Combine(home, ".copilot"));
        yield return ResolvePath(Path.Combine(home, ".config", "opencode"));
        yield return ResolvePath(Path.Combine(home, ".local", "share", "opencode"));

        var copilotHome = Environment.GetEnvironmentVariable("COPILOT_HOME");
        if (!string.IsNullOrEmpty(copilotHome))
        {
            yield return ResolvePath(copilotHome);
        }

        var xdgConfigHome = Environment.GetEnvironmentVariable("XDG_CONFIG_HOME");
        var configRoot = string.IsNullOrEmpty(xdgConfigHome) ? Path.Combine(home, ".config") : xdgConfigHome;
        yield return ResolvePath(Path.Combine(configRoot, "opencode"));

        var opencodeConfigDir = Environment.GetEnvironmentVariable("OPENCODE_CONFIG_DIR");
        if (!string.IsNullOrEmpty(opencodeConfigDir))
        {
            yield return ResolvePath(opencodeConfigDir);
        }

        var xdgDataHome = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
        var dataRoot = string.IsNullOrEmpty(xdgDataHome) ? Path.Combine(home, ".local", "share") : xdgDataHome;
        yield return ResolvePath(Path.Combine(dataRoot, "opencode"));
    }

    private static IEnumerable<string> EnumeratePlannedPaths(string outDir, string runtime)
    {
        yield return outDir;
        foreach (var name in CrossRuntimeReviewFiles.RenderedFor(runtime))
        {
            yield return Path.Combine(outDir, name);
        }
    }

    private static bool TryValidateExistingPlannedPath(string path, string resolvedOutDir, out string detail)
    {
        detail = string.Empty;
        if (!Path.Exists(path))
        {
            return true;
        }

        if (IsSymlink(path))
        {
            detail = $"planned path '{path}' is a symlink.";
            return false;
        }

        var resolved = ResolvePath(path);
        if (!IsInside(resolved, resolvedOutDir) && !PathEquals(resolved, resolvedOutDir))
        {
            detail = $"planned path '{path}' resolves outside the out-dir.";
            return false;
        }

        var fileName = Path.GetFileName(path);
        if (fileName is not null
            && RenderedFileNames.Contains(fileName)
            && Path.Exists(path)
            && !IsRegularFile(path))
        {
            detail = $"planned rendered path '{path}' is not a regular file.";
            return false;
        }

        return true;
    }

    private static readonly HashSet<string> RenderedFileNames = new(StringComparer.Ordinal)
    {
        CrossRuntimeReviewFiles.Prompt,
        CrossRuntimeReviewFiles.Schema,
        CrossRuntimeReviewFiles.Invocation,
        CrossRuntimeReviewFiles.OpencodeReviewerConfig,
    };

    internal static bool IsRegularFile(string path)
    {
        if (Directory.Exists(path))
        {
            return false;
        }

        if (!File.Exists(path))
        {
            return false;
        }

        var info = new FileInfo(path);
        if (info.Attributes.HasFlag(FileAttributes.ReparsePoint)
            || (info.Attributes & FileAttributes.Directory) != 0)
        {
            return false;
        }

        if (!OperatingSystem.IsWindows()
            && CrossRuntimeReviewFileMode.TryGetUnixFileMode(path, out var mode))
        {
            return (mode & 0xF000) == 0x8000;
        }

        return true;
    }

    internal static string ResolvePath(string path)
    {
        try
        {
            return ResolveRealPath(Path.GetFullPath(path));
        }
        catch (IOException)
        {
            return Path.GetFullPath(path);
        }
        catch (UnauthorizedAccessException)
        {
            return Path.GetFullPath(path);
        }
    }

    private static string ResolveRealPath(string path)
    {
        if (OperatingSystem.IsWindows())
        {
            return ResolveWindowsRealPath(path);
        }

        return ResolveUnixRealPath(path);
    }

    private static string ResolveUnixRealPath(string path)
    {
        if (!path.StartsWith('/'))
        {
            return path;
        }

        var segments = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
        var resolved = "/";
        for (var index = 0; index < segments.Length; index++)
        {
            var segment = segments[index];
            if (segment == ".")
            {
                continue;
            }

            if (segment == "..")
            {
                if (resolved.Length > 1)
                {
                    resolved = resolved[..resolved.LastIndexOf('/')];
                    if (resolved.Length == 0)
                    {
                        resolved = "/";
                    }
                }

                continue;
            }

            var current = resolved == "/" ? "/" + segment : resolved + "/" + segment;
            if (!File.Exists(current) && !Directory.Exists(current))
            {
                var tail = string.Join('/', segments.Skip(index + 1));
                return tail.Length == 0 ? current : current + "/" + tail;
            }

            if (IsSymlink(current))
            {
                var info = File.Exists(current) ? (FileSystemInfo)new FileInfo(current) : new DirectoryInfo(current);
                var target = info.ResolveLinkTarget(true)?.FullName ?? current;
                var remainder = string.Join('/', segments.Skip(index + 1));
                var combined = remainder.Length == 0 ? target : Path.Combine(target, remainder.Replace('/', Path.DirectorySeparatorChar));
                return ResolveUnixRealPath(Path.GetFullPath(combined));
            }

            resolved = current;
        }

        return resolved;
    }

    private static string ResolveWindowsRealPath(string path)
    {
        if (!File.Exists(path) && !Directory.Exists(path))
        {
            return path;
        }

        var info = File.Exists(path) ? (FileSystemInfo)new FileInfo(path) : new DirectoryInfo(path);
        var target = info.ResolveLinkTarget(true);
        return Path.GetFullPath(target?.FullName ?? info.FullName);
    }

    private static bool PathsOverlap(string left, string right)
    {
        if (PathEquals(left, right))
        {
            return true;
        }

        return IsInside(left, right) || IsInside(right, left);
    }

    private static bool PathEquals(string left, string right) =>
        string.Equals(
            TrimTrailingSeparator(left),
            TrimTrailingSeparator(right),
            StringComparison.OrdinalIgnoreCase);

    private static bool IsInside(string path, string root)
    {
        var normalizedPath = TrimTrailingSeparator(path);
        var normalizedRoot = TrimTrailingSeparator(root);
        var prefix = normalizedRoot + Path.DirectorySeparatorChar;
        return normalizedPath.StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
    }

    private static string TrimTrailingSeparator(string path)
    {
        var trimmed = path.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        return trimmed.Length == 0 ? path : trimmed;
    }

    private static bool IsSymlink(string path)
    {
        try
        {
            if (!File.Exists(path) && !Directory.Exists(path))
            {
                var parent = Path.GetDirectoryName(path);
                if (string.IsNullOrEmpty(parent) || !Directory.Exists(parent))
                {
                    return false;
                }

                var name = Path.GetFileName(path);
                foreach (var entry in Directory.EnumerateFileSystemEntries(parent))
                {
                    if (!string.Equals(Path.GetFileName(entry), name, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    var entryInfo = new FileInfo(entry);
                    return entryInfo.Attributes.HasFlag(FileAttributes.ReparsePoint);
                }

                return false;
            }

            var info = File.Exists(path) ? (FileSystemInfo)new FileInfo(path) : new DirectoryInfo(path);
            return info.Attributes.HasFlag(FileAttributes.ReparsePoint);
        }
        catch (IOException)
        {
            return true;
        }
        catch (UnauthorizedAccessException)
        {
            return true;
        }
    }
}

