using System.Text;

namespace IntentSystem.Cli.Commands;

internal static class CrossRuntimeReviewRequestSupport
{
    internal static bool TryValidateOutDir(
        string outDir,
        string runtime,
        TextWriter writer,
        string format,
        out string errorCause)
    {
        errorCause = string.Empty;
        if (File.Exists(outDir))
        {
            RefuseOutDir(writer, format, CrossRuntimeReviewCauses.PathInvalid,
                $"--out-dir '{outDir}' is a file.", "pass a new or empty directory.");
            return false;
        }

        if (!Directory.Exists(outDir))
        {
            if (CrossRuntimeReviewHomeAccessGuard.TryRefusePlannedPaths(outDir, runtime, out var plannedDetail))
            {
                RefuseOutDir(writer, format, CrossRuntimeReviewCauses.PathInvalid, plannedDetail,
                    "pass an out-dir outside the operator's Copilot home and OpenCode config directories.");
                return false;
            }

            return true;
        }

        if (CrossRuntimeReviewHomeAccessGuard.TryRefuseProtectedPath(outDir, out var protectedDetail))
        {
            RefuseOutDir(writer, format, CrossRuntimeReviewCauses.PathInvalid, protectedDetail,
                "pass an out-dir outside the operator's Copilot home and OpenCode config directories.");
            return false;
        }

        if (CrossRuntimeReviewHomeAccessGuard.TryRefusePlannedPaths(outDir, runtime, out var overlapDetail))
        {
            RefuseOutDir(writer, format, CrossRuntimeReviewCauses.PathInvalid, overlapDetail,
                "pass an out-dir outside the operator's Copilot home and OpenCode config directories.");
            return false;
        }

        var rendered = CrossRuntimeReviewFiles.RenderedFor(runtime);
        var foreign = Directory.EnumerateFileSystemEntries(outDir)
            .Select(Path.GetFileName)
            .Where(name => name is not null && !rendered.Contains(name, StringComparer.Ordinal))
            .OrderBy(name => name, StringComparer.Ordinal)
            .ToArray();
        if (foreign.Length > 0)
        {
            RefuseOutDir(writer, format, CrossRuntimeReviewCauses.OutDirNotEmpty,
                $"--out-dir '{outDir}' contains other entries: {string.Join(", ", foreign)}.",
                "pass a new or empty directory so a stale verdict can never be mixed with this request.");
            return false;
        }

        foreach (var directoryName in CrossRuntimeReviewRuntimes.IsolationDirectories(runtime))
        {
            var path = Path.Combine(outDir, directoryName);
            if (Path.Exists(path))
            {
                var detail = Directory.Exists(path)
                    ? $"--out-dir '{outDir}' contains a directory named '{directoryName}'."
                    : $"--out-dir '{outDir}' contains a file named '{directoryName}'.";
                RefuseOutDir(writer, format, CrossRuntimeReviewCauses.OutDirNotEmpty, detail,
                    "pass a new or empty directory.");
                return false;
            }

            if (Directory.Exists(path) && Directory.EnumerateFileSystemEntries(path).Any())
            {
                RefuseOutDir(writer, format, CrossRuntimeReviewCauses.OutDirNotEmpty,
                    $"--out-dir '{outDir}' contains a non-empty directory '{directoryName}'.",
                    "pass a new or empty directory.");
                return false;
            }
        }

        return true;
    }

    internal static IReadOnlyList<string> WriteRequestFiles(
        string runtime,
        string outDir,
        string prompt,
        string schema,
        string invocation,
        string? opencodeProviderConfigPath)
    {
        if (CrossRuntimeReviewHomeAccessGuard.TryRefusePlannedPaths(outDir, runtime, out var plannedDetail))
        {
            throw new InvalidOperationException(plannedDetail);
        }

        var utf8 = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);
        Directory.CreateDirectory(outDir);
        WriteUtf8File(Path.Combine(outDir, CrossRuntimeReviewFiles.Prompt), prompt, utf8);
        WriteUtf8File(Path.Combine(outDir, CrossRuntimeReviewFiles.Schema), schema, utf8);
        WriteUtf8File(Path.Combine(outDir, CrossRuntimeReviewFiles.Invocation), invocation, utf8);

        foreach (var directoryName in CrossRuntimeReviewRuntimes.IsolationDirectories(runtime))
        {
            var path = Path.Combine(outDir, directoryName);
            if (!Directory.Exists(path))
            {
                Directory.CreateDirectory(path);
            }
        }

        if (runtime == CrossRuntimeReviewRuntimes.Opencode)
        {
            WriteBytesFile(
                Path.Combine(outDir, CrossRuntimeReviewFiles.OpencodeReviewerConfig),
                CrossRuntimeReviewOpencodeConfig.ReviewerConfigBytes(opencodeProviderConfigPath));
        }

        return CrossRuntimeReviewFiles.RenderedFor(runtime)
            .Select(name => Path.Combine(outDir, name))
            .ToArray();
    }

    private static void WriteUtf8File(string path, string content, UTF8Encoding encoding)
    {
        var directory = Path.GetDirectoryName(path)!;
        var temp = Path.Combine(directory, $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
        File.WriteAllText(temp, content, encoding);
        File.Move(temp, path, overwrite: true);
    }

    private static void WriteBytesFile(string path, byte[] content)
    {
        var directory = Path.GetDirectoryName(path)!;
        var temp = Path.Combine(directory, $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
        File.WriteAllBytes(temp, content);
        File.Move(temp, path, overwrite: true);
    }

    private static void RefuseOutDir(TextWriter writer, string format, string cause, string detail, string fix)
    {
        if (format == "json")
        {
            writer.WriteLine(System.Text.Json.JsonSerializer.Serialize(new CrossRuntimeReviewRefusal
            {
                Command = $"{ReviewCrossRuntimeCommand.CommandName} request",
                Outcome = "refused",
                Cause = cause,
                Detail = detail,
                Fix = fix,
            }));
            return;
        }

        writer.WriteLine($"Refused: {cause}");
        writer.WriteLine(detail);
        writer.WriteLine(fix);
    }
}

